.pds-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pds-root,.pds-root *,.pds-root *::before,.pds-root *::after{box-sizing:border-box}
.pds-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pds-root img{display:block;border:0;max-width:none}
.pds-root > [data-node-id]{will-change:transform}
.pds-root [hidden]{display:none!important}
.pds-root [data-sh-theme="dark"]{display:none!important}
.pds-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.pds-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.pds-root .n3300_6229{align-content:stretch;display:flex;gap:3.41px;height:13.17px;align-items:flex-start;position:relative;flex-shrink:0;width:116px}
.pds-root .n3300_6288{align-content:stretch;display:flex;align-items:flex-start;padding-top:0.03px;position:relative;flex-shrink:0}
.pds-root .n3300_5563{background-color:var(--wa-point, #2f6df0);height:12px;position:relative;border-radius:3px;flex-shrink:0;width:11.59px}
.pds-root .n3300_5562{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;line-height:13px;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:var(--wa-text, #000);width:40px;white-space:nowrap}
.pds-root .n3300_6289{align-content:stretch;display:flex;align-items:flex-start;padding-left:7.59px;padding-top:0.17px;position:relative;flex-shrink:0}
.pds-root .n3300_5561{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:300;line-height:13px;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:var(--wa-text, #000);width:50px;white-space:nowrap}
.pds-root [data-name^="Card/Stage"] p{letter-spacing:-0.05em;word-break:keep-all}
.pds-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.pds-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > div{background:linear-gradient(180deg,var(--wa-bg, #0d1117) 0%,var(--wa-bg, #111821) 100%)!important}
.pds-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > img{opacity:.04!important;filter:invert(1)}
.pds-root[data-theme="dark"] [data-name="Stage/3D Scene"] img{filter:brightness(.9) saturate(.95) contrast(1.03)}
.pds-root[data-theme="dark"] [data-name="Stage/Building Image"] img{filter:brightness(.86) contrast(1.04)}
.pds-root[data-theme="dark"] [data-name="Side Rail"],.pds-root[data-theme="dark"] [data-name="Filter Panel"] [data-name="Rectangle 4"]{background:color-mix(in srgb, var(--wa-bg, rgb(20 23 29)) 84%, transparent)!important;box-shadow:0 0 0 1px rgba(255,255,255,.07),0 12px 28px rgba(0,0,0,.35)!important;-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px)}
.pds-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Background"],.pds-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Header Background"]{background:var(--wa-bg, #12151b)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.07)!important}
.pds-root[data-theme="dark"] svg [fill="#FCFCFC"]:not(mask *),.pds-root[data-theme="dark"] svg [fill="#fcfcfc"]:not(mask *),.pds-root[data-theme="dark"] svg [fill="white"]:not(mask *),.pds-root[data-theme="dark"] svg [fill="#F9F9F9"]:not(mask *){fill:var(--wa-surface, #15181e)}
.pds-root[data-theme="dark"] svg [stroke="#F1F1F1"]:not(mask *),.pds-root[data-theme="dark"] svg [stroke="#f1f1f1"]:not(mask *),.pds-root[data-theme="dark"] svg [fill="#F1F1F1"]:not(mask *){stroke:var(--wa-line, #2a2e36)}
.pds-root[data-theme="dark"] svg path[fill="#F1F1F1"]:not(mask *){fill:var(--wa-surface, #2a2e36)}
.pds-root[data-theme="dark"] [data-name="Event Log"] [data-name^="Row/"]:hover,.pds-root[data-theme="dark"] [data-name="Event Log"] [data-name="grid-row"]:hover{filter:brightness(1.15)}
.pds-root[data-theme="dark"] [data-name="Tooltip Group"] [data-name^="Tooltip/"] p{color:var(--wa-text, #e6ebf2)!important}
.pds-root[data-theme="dark"] [data-name^="Category/"] img{content:normal!important}
.pds-root[data-theme="dark"] .n3300_5562{color:var(--wa-text, #eceef2)}
.pds-root[data-theme="dark"] .n3300_5561{color:var(--wa-text, #eceef2)}
